55	const PROCESSING_FEE = 5;
56	
57	const FIRST_INSURANCE_SURCHARGE = 0.1;
58	
59	const BASE_PREMIUMS: Record<string, number> = {
60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	  potion: 40,
64	  rune: 25,
65	  moonstone: 25,
66	};
67	
68	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
69	
70	const BLOCK_SIZE = 3;
71	const BLOCK_BASE_PREMIUM = 60;
72	
73	const formsBuildingBlock = (items: Item[]): boolean =>
74	  items.length === BLOCK_SIZE && items.every((item) => item.type === items[0].type);
75	
76	const sumOfItemBasePremiums = (items: Item[]): number =>
77	  items.reduce((sum, item) => sum + itemBasePremium(item), 0);
78	
79	const policyBasePremium = (items: Item[]): number =>
80	  formsBuildingBlock(items) ? BLOCK_BASE_PREMIUM : sumOfItemBasePremiums(items);
81	
82	const withFirstInsuranceSurcharge = (policyBase: number): number =>
83	  policyBase + policyBase * FIRST_INSURANCE_SURCHARGE;
84	
85	const roundInMHPCOsFavor = Math.ceil;
86	
87	const quotePremium = (items: Item[]): number =>
88	  roundInMHPCOsFavor(withFirstInsuranceSurcharge(policyBasePremium(items)) + PROCESSING_FEE);
89	
90	const runStep = (step: Step): StepResult => {
91	  if (step.op === "quote") {
92	    return { premium: quotePremium(step.items) };
93	  }
94	  throw new Error(`Unsupported step: ${step.op}`);
95	};
96	
97	export const runScenario = (scenario: Scenario): ScenarioResult => ({
98	  results: scenario.steps.map(runStep),
99	});
